package com.bank.autoloader;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.logging.Logger;

// Simulates cloud object storage: files arrive over time; optional notification queue.
class CloudStorage {
    private static final Logger log = Logger.getLogger(CloudStorage.class.getName());

    private final Map<String, String> files = new LinkedHashMap<>(); // name -> csv content
    private final Queue<String> notificationQueue = new ConcurrentLinkedQueue<>();

    void dropFile(String name, String content) {
        files.put(name, content);
        notificationQueue.add(name); // storage emits an arrival event
        log.info(() -> "File arrived in cloud storage: " + name);
    }

    // Listing mode: return ALL file names (expensive at scale).
    List<String> listAll() { return new ArrayList<>(files.keySet()); }

    // Notification mode: drain only the new-arrival events.
    List<String> drainNotifications() {
        List<String> newOnes = new ArrayList<>();
        String n;
        while ((n = notificationQueue.poll()) != null) newOnes.add(n);
        return newOnes;
    }

    String content(String name) { return files.get(name); }
}
