package com.bank.autoloader;

import java.util.HashSet;
import java.util.Set;
import java.util.logging.Logger;

// The streaming checkpoint: which files have already been processed (exactly-once).
class Checkpoint {
    private static final Logger log = Logger.getLogger(Checkpoint.class.getName());

    private final Set<String> processed = new HashSet<>();

    boolean alreadyProcessed(String file) { return processed.contains(file); }

    void markProcessed(String file) {
        processed.add(file);
        log.fine(() -> "Checkpoint committed: " + file);
    }

    int size() { return processed.size(); }
}
