package com.bank.autoloader;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// The bronze Delta table receiving raw ingested rows.
class BronzeTable {
    private static final Logger log = Logger.getLogger(BronzeTable.class.getName());

    final List<String> columns = new ArrayList<>(List.of("trade_id", "account_id", "amount"));
    final List<String> rows = new ArrayList<>();

    void addColumnIfNew(String col) {
        if (!columns.contains(col)) {
            columns.add(col);
            log.warning(() -> "Schema evolution: added new column '" + col + "' to bronze table");
        }
    }

    void append(String row) { rows.add(row); }

    int rowCount() { return rows.size(); }
}
