package com.bank.autoloader;

import java.util.List;
import java.util.logging.Logger;

// The cloudFiles source: incremental, exactly-once, listing or notification, schema evolution.
class AutoLoader {
    private static final Logger log = Logger.getLogger(AutoLoader.class.getName());

    private final CloudStorage storage;
    private final Checkpoint checkpoint;
    private final BronzeTable bronze;
    private boolean useNotifications;

    AutoLoader(CloudStorage storage, Checkpoint checkpoint, BronzeTable bronze, boolean useNotifications) {
        this.storage = storage;
        this.checkpoint = checkpoint;
        this.bronze = bronze;
        this.useNotifications = useNotifications;
    }

    void setUseNotifications(boolean v) {
        this.useNotifications = v;
        log.info(() -> "Auto Loader discovery mode = " + (v ? "file NOTIFICATIONS (scales)" : "directory LISTING"));
    }

    // One micro-batch trigger: pick up only NEW files and process each exactly once.
    int trigger() {
        List<String> candidates = useNotifications ? storage.drainNotifications() : storage.listAll();
        int processedNow = 0;
        for (String file : candidates) {
            if (checkpoint.alreadyProcessed(file)) {
                continue; // exactly-once: never reprocess
            }
            processFile(file);
            checkpoint.markProcessed(file);
            processedNow++;
        }
        int done = processedNow;
        log.info(() -> "Trigger processed " + done + " NEW file(s); checkpoint now has " + checkpoint.size());
        return processedNow;
    }

    // Parses a file, evolving the schema if an extra column appears, rescuing extras.
    private void processFile(String file) {
        String content = storage.content(file);
        for (String line : content.split("\n")) {
            String[] parts = line.split(",");
            // Columns beyond the base 3 are new → schema evolution.
            if (parts.length > 3) bronze.addColumnIfNew("fee");
            bronze.append(line);
        }
        log.info(() -> "Ingested file " + file);
    }
}
