package com.bank.autoloader;

import java.util.logging.Logger;

public class AutoLoaderDemo {
    private static final Logger log = Logger.getLogger(AutoLoaderDemo.class.getName());

    public static void main(String[] args) {
        CloudStorage storage = new CloudStorage();
        Checkpoint checkpoint = new Checkpoint();
        BronzeTable bronze = new BronzeTable();
        AutoLoader loader = new AutoLoader(storage, checkpoint, bronze, false);

        // Wave 1: two files arrive, Auto Loader ingests both.
        storage.dropFile("trades_0900.csv", "TRD-1,SAV2001,50000");
        storage.dropFile("trades_1000.csv", "TRD-2,CUR3001,80000");
        loader.trigger();

        // Wave 2: one new file arrives — only the NEW file is processed (old ones skipped).
        storage.dropFile("trades_1100.csv", "TRD-3,SAV2001,30000");
        loader.trigger();

        // Restart simulation: a new trigger with the SAME checkpoint processes nothing new.
        log.info("=== After restart (same checkpoint) ===");
        loader.trigger();

        // Switch to notification mode for scale.
        loader.setUseNotifications(true);

        // Wave 3: a file with a NEW column (fee) → schema evolution.
        storage.dropFile("trades_1200.csv", "TRD-4,CUR3001,20000,250");
        loader.trigger();

        log.info(() -> "Bronze table columns = " + bronze.columns + ", rows = " + bronze.rowCount());
    }
}
